def f(datasets: List[Tuple[int, List[int]]]) -> List[int]:
    result = []
    for n, s in datasets:
        total = sum(s)
        if total % n == 0:
            avg = total // n
            max_val = max(s)
            min_val = min(s)
            if avg == max_val and avg == min_val:
                result.append(1)
            else:
                result.append(0)
        else:
            result.append(0)
    return result
```

